// Fill only small, fully enclosed background components. Border-connected space is retained.
function monochromeSilhouette(labels,width,height,transparent,maxArea){const seen=new Uint8Array(labels.length),queue=new Int32Array(labels.length);for(let seed=0;seed<labels.length;seed++){if(seen[seed]||labels[seed]===0)continue;let head=0,tail=0,touchesEdge=false;queue[tail++]=seed;seen[seed]=1;while(head<tail){const i=queue[head++],x=i%width,y=Math.floor(i/width);if(x===0||y===0||x===width-1||y===height-1)touchesEdge=true;for(const j of [x>0?i-1:-1,x<width-1?i+1:-1,y>0?i-width:-1,y<height-1?i+width:-1])if(j>=0&&!seen[j]&&labels[j]!==0){seen[j]=1;queue[tail++]=j;}}if(!touchesEdge&&tail<=maxArea)for(let k=0;k<tail;k++)labels[queue[k]]=0;}
 let foreground=0;for(let i=0;i<labels.length;i++){if(labels[i]===0)foreground++;else labels[i]=transparent;}if(!foreground)throw new Error('No black shapes found. Adjust the black threshold.');return labels;}
